// Normalizar el payload de Hotmart / ClickBank / ThriveCart a un formato unico.
// Ajustar aqui si la plataforma cambia su estructura.
const b = $input.first().json.body || $input.first().json;
const email = b?.data?.buyer?.email || b?.customer?.email || b?.email || '';
const nombre = b?.data?.buyer?.name || b?.customer?.name || b?.first_name || '';
const transaccion = b?.data?.purchase?.transaction || b?.receipt || b?.order_id || b?.transaction_id || '';
const plataforma = b?.data?.purchase ? 'Hotmart' : (b?.receipt ? 'ClickBank' : 'ThriveCart');
const idioma = (b?.data?.purchase?.checkout_country || '').match(/US|GB|CA|AU/) ? 'en' : 'es';
return [{ json: { email, nombre, transaccion, plataforma, idioma } }];

